package com.abluepoint.summer.sample.mcpauthorization.api;
import com.abluepoint.summer.sample.mcpauthorization.application.ExecutionPermitView;
import com.abluepoint.summer.sample.mcpauthorization.application.McpAuthorizationService;
import com.abluepoint.summer.sample.mcpauthorization.application.PermitClaimCommand;
import com.abluepoint.summer.sample.mcpauthorization.domain.McpAuthorizationValidationException;
import com.abluepoint.summer.sample.mcpauthorization.domain.McpAuthorizationConflictException;
import com.abluepoint.summer.sample.mcpauthorization.application.ExecutionDecisionCommand;
import com.abluepoint.summer.sample.mcpauthorization.application.PermitClaimView;
import com.abluepoint.summer.sample.mcpauthorization.application.ExecutionDecisionView;
import com.abluepoint.summer.common.response.api.*;import com.abluepoint.summer.mvc.response.api.RawResponse;import com.abluepoint.summer.mvc.request.api.RequestIdAccessor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @PreAuthorize("isAuthenticated()") class McpAuthorizationController{final McpAuthorizationService s;final RequestIdAccessor r;McpAuthorizationController(McpAuthorizationService s,RequestIdAccessor r){this.s=s;this.r=r;}
 @PostMapping(value="/internal/v1/mcp/execution-decisions",consumes=MediaType.APPLICATION_JSON_VALUE)@RawResponse ResponseEntity<ApiResponse<ExecutionDecisionView>> decide(@RequestBody ExecutionDecisionRequest q,Authentication a){try{return body(HttpStatus.OK,s.decide(q.toCommand(),a));}catch(Exception e){return err(e);}}
 @PostMapping(value="/internal/v1/mcp/execution-permits/{id}:claim",consumes=MediaType.APPLICATION_JSON_VALUE)@RawResponse ResponseEntity<ApiResponse<PermitClaimView>> claim(@PathVariable String id,@RequestBody PermitClaimRequest q,Authentication a){try{return body(HttpStatus.OK,s.claim(id,q.toCommand(),a));}catch(Exception e){return err(e);}}
 @PostMapping("/api/v1/enterprises/{e}/mcp-execution-permits/{id}:revoke")@RawResponse ResponseEntity<ApiResponse<ExecutionPermitView>> revoke(@PathVariable String e,@PathVariable String id,Authentication a){try{return body(HttpStatus.OK,s.revoke(e,id,a));}catch(Exception z){return err(z);}}
 private<T>ResponseEntity<ApiResponse<T>>body(HttpStatus h,T v){return ResponseEntity.status(h).header("X-Request-Id",r.currentRequestId()).body(ApiResponse.success(v,r.currentRequestId()));}private<T>ResponseEntity<ApiResponse<T>>err(Exception e){HttpStatus h=HttpStatus.INTERNAL_SERVER_ERROR;String c="SUMMER_INTERNAL_ERROR";if(e instanceof org.springframework.security.access.AccessDeniedException){h=HttpStatus.FORBIDDEN;c="SUMMER_FORBIDDEN";}else if(e instanceof McpAuthorizationValidationException){h=HttpStatus.BAD_REQUEST;c="SUMMER_MCP_AUTH_INVALID";}else if(e instanceof McpAuthorizationConflictException){h=HttpStatus.CONFLICT;c="SUMMER_MCP_AUTH_CONFLICT";}return ResponseEntity.status(h).header("X-Request-Id",r.currentRequestId()).body(ApiResponse.failure(new ApiError(c,e.getMessage(),List.of()),r.currentRequestId()));}}
